    data_section4: "Ինչով է բացառիկ Հայաստանը",
    data_unique1_title: "Աշխարհագրական դիրք, որը Հայաստանը դարձնում է բացառիկ",
    data_unique1_text:
      "Հայաստանը պարզապես երկիր չէ քարտեզի վրա։ Այն մի վայր է, որտեղ յուրահատուկ աշխարհագրությունն ու պատմական փորձառությունները միահյուսվում են՝ ստեղծելով ճամփորդության բացառիկ հնարավորություն։",
    data_unique2_title: "Լեռնային երկիր՝ արկածների սիրահարների համար",
    data_unique2_text:
      "Հայաստանը գծագրում է բնության կտրուկ լանդշաֆտներով։ Այստեղ լեռներ կան ամեն քայլափոխի, ինչը նշանակում է՝ բազմազան, այդ թվում՝ դժվարանցանելի արշավային ուղիներ, հիասքանչ դիտակետեր և լեռներից բացվող անզուգական արևածագեր։",
    data_unique2_text_italic:
      "«Դժվարանցանելի» մեզ մոտ նշանակում է՝ չբացահայտված և մաքուր բնություն։",
    data_unique3_title: "Միջմայրցամաքային մշակույթ",
    data_unique3_text:
      "Եվրոպայի և Ասիայի խաչմերուկում լինելը Հայաստանը դարձրել է քաղաքակրթությունների յուրօրինակ խառնուրդ։ Այստեղ կարող եք միաժամանակ զգալ հինավուրց արևելք, հելլենիստական ճարտարապետություն և սովետական ժառանգություն։",
    data_unique3_text_italic:
      "«Մշակույթների հանդիպման այս եզակի կետը զգում ես՝ հենց օդանավակայանից դուրս գալիս»։",
    data_unique4_title: "Ճանապարհներ՝ ոչ միայն ուղղություն, այլ փորձառություն",
    data_unique4_text:
      "Հայաստանում ճանապարհորդելը երբեմն դառնում է արկած։ Բոլոր ճանապարհները գերծանրաբեռնված չեն, և հենց դա է յուրահատկությունը։ Դուք կանցնեք լեռներով, գետերով ու հնագույն քարայրերով, որոնք հաճախ պատահում են այնպես, ինչպես դարեր առաջ։",
    data_unique4_text_italic:
      "*«GPS-ը կարող է սխալվել, բայց հին մարդը՝ երբեք»։",
    data_unique5_title: "Փակ սահմաններ, բայց բաց դռներ դեպի ներս",
    data_unique5_text:
      "Չնայած որոշ սահմաններ փակ են, Հայաստանը բաց է իր այցելուների առաջ։ Դա օգնում է կենտրոնանալ ներքին խաղաղության, հարուստ պատմության և տեղական մշակույթի վրա։",
    data_unique6_title: "Վայր, որտեղ ժամանակը շարժվում է այլ ռիթմով",
    data_unique6_text:
      "Այստեղ մարդիկ դեռ ասում են բարև, հյուրասիրում են առանց սպասելու։ Դուք կարող եք մոռանալ քաղաքի աղմուկը և վերագտնել պարզ ու մարդկային կապերը։",
