    description_bnakchutyun_sub3:
      "Երևանում բնակվում է շուրջ 1 075 800 մարդ (ՀՀ բնակչության ≈37%) 2022թ. տվյալներով, ըստ բնակչության թվի՝ առաջատարը Երևանն է, որը կենտրոնացնում է երկրի վարչական, տնտեսական, մշակութային և զբոսաշրջային կյանքը։ Մարզերում բնակչության թիվը զգալիորեն տարբեր է՝ Կոտայք՝ մոտ",
