    data_border_pre2020:
      "Before the 44-day war of 2020, the border length between Armenia and Artsakh was about 850 km (including the security zone).",
    data_border_route:
      "The state border runs along the Araks River; with Georgia it passes through the Javakheti plateau, the Lori plain and the Virahayots mountains; with Turkey it runs through the Yeghnagakh plateau, the Akhurian and Araks rivers; with Azerbaijan it goes through the Vayots Dzor, Zangezur and Sevan mountain ranges. The country is surrounded from the north and east by the Lesser Caucasus mountain range.",
    data_map_sub: "Geographic map of the region",
    data_river_sub: "Araks River",
    data_section4: "What Makes Armenia Unique",
    data_unique1_title: "A geographic position that makes Armenia exceptional",
    data_unique1_text:
      "Armenia is not just a country on a map. It is a place where unique geography and historical experiences intertwine, creating an exceptional travel opportunity.",
    data_unique2_title: "A mountainous country for adventure lovers",
    data_unique2_text:
      "Armenia is marked by its rugged natural landscapes. There are mountains at every turn, which means a variety of hiking trails, including difficult hiking trails, magnificent viewpoints, and unparalleled sunrises from the mountains.",
    data_unique2_text_italic:
      "'Hard-to-reach' here means undiscovered and pristine nature.",
    data_unique3_title: "Intercontinental culture",
    data_unique3_text:
      "Being at the crossroads of Europe and Asia has made Armenia a unique blend of civilizations. Here you can simultaneously feel ancient Eastern traditions, Hellenistic architecture and Soviet heritage.",
    data_unique3_text_italic:
      "‘Hard-to-reach’ here means undiscovered and pristine nature.",
    data_unique4_title: "Roads — not just directions, but experiences",
    data_unique4_text:
      "Traveling in Armenia can sometimes be an adventure. Not all roads are congested, and that's what makes it special. You'll pass through mountains, rivers, and ancient caves, often looking as they did centuries ago.",
    data_unique4_text_italic: "*GPS can be wrong, but an old man never is.",
    data_unique5_title: "Closed borders, but open doors within",
    data_unique5_text:
      "Although some borders are closed, Armenia is open to its visitors. This helps to focus on its inner peace, rich history, and local culture.",
    data_unique6_title: "A place where time moves at a different rhythm",
    data_unique6_text:
      "People here still say hello and offer hospitality without waiting. You can forget the noise of the city and rediscover simple human connections.",
    data_quote:
      '"Behind closed doors, a whole world opens up — warm and sincere"',
