    get_page_title: "How to reach Armenia",
    get_transport_subtitle: "Transport / Entry information",
    get_intro:
      "Armenia is accessible by major means of transportation: air, rail, and road. There is no water access, but developed land connections make it easy to visit the country.",
    get_li1: "Air transport",
    get_li2: "Transport to the city",
    get_li3: "Railway",
    get_li4: "Contacts and addresses",
    get_air_title: "Air transport",
    get_air_p1:
      "Zvartnots International Airport and Shirak Airport, which operates in Gyumri. Zvartnots, the air gateway of Armenia, is the main airport of the Republic of Armenia, located 12 km from the center of Yerevan. The airport serves direct flights to 50+ cities in Europe, Asia and the Middle East, cooperating with more than 30 airlines and 50+ destinations (Moscow, Paris, Vienna, Dubai, Istanbul, etc.).",
    get_air_p2:
      "The airport offers direct flights from more than 50 cities around the world: London, Paris, Vienna, Moscow, Dubai, Tehran, Istanbul, etc. There are also budget flights to European destinations: Warsaw, Milan, Barcelona, ​​Eindhoven, etc.",
    get_airlines:
      "Airlines: Aeroflot, Air France, Austrian Airlines, Fly Arna, Armenia Airways, etc. The national carriers of Armenia are Fly Arna and Air Armenia, which carry out passenger and cargo transportation to the CIS and Europe.",
    get_airlines_label: "Airlines",
