    get_srv4:
      "Possibility to get a visa at the airport upon arrival (up to 21 days - 3,000 AMD)",
    get_srv5: "Special VIP services for business travelers and honored guests",
    get_transfer_title: "Transfers from airport to Yerevan",
    get_minibus: "Express minibus",
