      "Download the Zvartnots app to get flight information and book tickets",
    get_rail_title: "Rail transport",
    get_rail_p1:
      "The South Caucasus Railway operates in Armenia, which provides passenger transportation to Georgia. It operates about 725 km of electrified line. The main stations are Yerevan, Gyumri and Vanadzor. Active international routes:",
    get_rail_route: "Ayrum – Sadakhlo (Georgia)",
    get_station_title: "Yerevan Railway Station (Sasuntsi Davit)",
    get_station_p1:
      "Yerevan's main railway station, named after the epic hero David of Sasun, is located on Tigran Mets Avenue. A statue of David on horseback, holding a sword in his hand, stands in front of the station as a symbol of national endurance and inspiration. Yerevan's David of Sasun railway station serves passenger services to Georgia and within the country.",
    get_station_services: "Services operating at Yerevan station:",
    get_st1: "International and suburban halls",
    get_st2: "VIP and waiting rooms",
    get_st3: "ATM, Wi-Fi, coffee machines",
    get_st4: "Information staff, tourist info point",
    get_st5: "Ticket sales to various cities in Russia (ASU 'Express')",
    get_symbol: "Symbol: Equestrian statue of Sasuntsi Davit",
    get_museum:
      "Museum dedicated to the history of the Armenian railway, with free admission",
    get_lines: "Lines: to Georgia, domestic passenger transportation",
    get_to_georgia: "Rail connection from Yerevan to Georgia",
    get_geo1: "Trips start from Yerevan Sasuntsi Davit station",
    get_geo2: "Trains are moving towards Tbilisi, with night service.",
    get_geo3: "An affordable and convenient travel option",
    get_travel_slogan: "Travel the path of Sasuntsi Davit",
    get_addr: "Address: Yerevan, 80 Tigran Mets Ave",
    get_info_num: "Info: 1-84 / +374 60 46 32 84",
    get_hours: "Open 24/7, info desk daily 07:30–19:30",
    get_ticket_office: "Ticket office open daily",

    // climate.html
    hayastan_climate_head_title: "Climate",
    climate_label: "Overview",
    climate_page_title: "Climate",
    climate_intro:
      "Armenia, being a mountainous country, has an exceptional climatic diversity. Almost all climatic zones are found here, from subtropical to alpine.",
    climate_zones_title: "Climate zones by altitude",
    climate_col1: "Climate type",
    climate_col2: "Elevation above sea level",
    climate_row1_type: "Dry subtropical",
    climate_row1_alt: "Up to 900 m",
    climate_row2_type: "Dry continental",
    climate_row2_alt: "Up to 1300 m",
    climate_row3_type: "Moderately warm arid",
    climate_row3_alt: "1200 – 1700 m",
    climate_row4_type: "Temperate",
    climate_row4_alt: "Up to 2000 m",
    climate_row5_type: "Mountain cold",
    climate_row5_alt: "Up to 3500 m",
    climate_row6_type: "Highland",
    climate_row6_alt: "Over 3500 m",
    climate_temp_title: "Temperature",
    climate_temp_summer: "Summer: hot and sunny (+30°–+35°C)",
    climate_temp_winter: "Winter: short, but cold (-15°–-20°C)",
    climate_temp_sunny: "Average number of sunny days per year: about 270",
    climate_temp_hottest:
      "The hottest region is the Ararat Valley, sometimes up to +42°C",
    climate_precip_title: "Locations",
    climate_precip1: "Average annual precipitation: ~ 640 mm",
    climate_precip2: "Uneven precipitation: 250–850 mm, depending on the area",
    climate_precip3:
      "The wettest place is the Hankavan Mountains (up to 850 mm)",
    climate_precip4: "The driest is the Meghri River Valley (~250 mm)",
    climate_precip5: "In some places there is almost no snow",
    climate_wind_title: "Winds",
    climate_wind1: "Mountain and valley winds in Yerevan in the afternoon",
    climate_wind2: "'Mantash wind' from the Aragats regions",
    climate_wind3: "Winds up to 40 m/s in mountain passes",
    climate_wind4: "Mountain winds in Gyumri, Yeghnagra, Shirak mountains",
    climate_features_title: "Climate features",
    climate_feat1: "A sharp change in climate is possible in 1–2 hours",
    climate_feat2:
      "Northwest-southeast stretching mountains protect from northern winds",
    climate_feat3:
      "Moisture coming from the Black and Caspian Seas is limited, causing a dry climate",
    climate_feat4:
      "The Ararat Valley is more exposed to the influence of the Iranian Plateau",
    climate_irrig_title: "Landslides and irrigation",
    climate_irrig_text:
      "Precipitation is low in low-lying regions, so artificial irrigation is used for agriculture. Armenia has had a developed system of canals since ancient times.",

