    hayastan_info55:
      "To dial a city number in Yerevan from a mobile phone, you must first dial 010, then the given number",
    hayastan_info56: "Mobile connection",
    hayastan_info57:
      "Mobile communication and mobile Internet in Armenia are provided by three operators:",
    hayastan_info58: "Mobile operators",
