    data_border_current_total:
      "В настоящее время общая длина границы между Арменией и Азербайджаном составляет примерно 1055 км.",
    data_border_pre2020:
      "До 44-дневной войны 2020 года длина границы между РА и Карабахом составляла примерно 850 км (включая зону безопасности).",
    data_border_route:
      "Государственная граница проходит по реке Аракс. С Грузией — через плато Джавахетия, долину Лори и горы Вирахаец; с Турцией — через плато Егнакх, реки Ахурян и Аракс; с Азербайджаном — через Вайоц Дзор, Зангезур и хребет Севан. Страна с севера и востока окружена горными хребтами Малого Кавказа.",
    data_map_sub: "Географическая карта региона",
    data_river_sub: "Река Аракс",
    data_section4: "Чем уникальна Армения",
    data_unique1_title: "Географическое положение, делающее Армению уникальной",
    data_unique1_text:
      "Армения — это не просто страна на карте. Это место, где уникальная география и исторический опыт переплетаются, создавая исключительные возможности для путешествий.",
    data_unique2_title: "Горная страна для любителей приключений",
    data_unique2_text:
      "Армения отличается суровыми природными ландшафтами. Горы встречаются на каждом шагу, что означает разнообразие пешеходных маршрутов, включая сложные, великолепные смотровые площадки и непревзойденные восходы солнца в горах.",
    data_unique3_title: "Межконтинентальная культура",
    data_unique3_text:
      "Находясь на перекрёстке Европы и Азии, Армения стала уникальным сплавом цивилизаций.",
    data_unique3_text_italic:
      "«Трудно доступное» у нас означает неоткрытую и чистую природу.",
    data_unique4_title: "Дороги — не просто направление, а опыт",
    data_unique4_text:
      "Путешествие по Армении порой может стать настоящим приключением. Не все дороги перегружены, и именно это делает её особенной. Вы будете проезжать через горы, реки и древние пещеры, которые часто выглядят так же, как и столетия назад.",
    data_unique4_text_italic:
      "«GPS может ошибаться, но старик никогда не ошибается».",
    data_unique5_title: "Закрытые границы, но открытые двери внутри",
    data_unique5_text:
      "Несмотря на то, что некоторые границы закрыты, Армения открыта для своих посетителей. Это позволяет сосредоточиться на внутреннем спокойствии, богатой истории и местной культуре.",
    data_unique6_title: "Место, где время движется в другом ритме",
    data_unique6_text:
      "Здесь люди всё ещё здороваются и угощают без ожидания. Вы можете забыть о городском шуме и вновь обрести простые человеческие связи.",
    data_quote:
      "«За закрытыми дверями открывается целый мир — тёплый и искренний»",
