    description_bnakchutyun_sub3:
      "Около 1 075 800 человек проживают в Ереване (≈37% населения Республики Армения). По данным 2022 года, лидером по численности населения является Ереван, в котором сосредоточена административная, экономическая, культурная и туристическая жизнь страны. Численность населения в регионах значительно различается: в Котайке около",
