    description_tntesutyun_title: "4. Экономика",
    description_tntesutyun_sub:
      "Армения — индустриально-аграрная страна, богатая природными ресурсами. Экономика традиционно делится на два основных сектора: материальное производство и нематериальный или сервисный сектор.",
    description_tntesutyun_item1:
      "Секторы — промышленность, сельское хозяйство, информационные технологии, туризм",
    description_tntesutyun_item2:
      "Основные экспортные товары — медь, молибден, алкогольные напитки (вино, бренди), сельскохозяйственная продукция",
    description_tntesutyun_item3:
      "Экономические проблемы — блокада, безопасность границ, отток рабочей силы",
    description_tntesutyun_title1: "Основные сектора экономики",
    description_tntesutyun_item4: "Промышленность",
    description_tntesutyun_item5: "Сельское хозяйство",
    description_tntesutyun_item6: "Торговля",
    description_tntesutyun_item7: "Туризм",
    description_tntesutyun_item8: "Информационные технологии (ИТ)",
    description_tntesutyun_title2: "Сектор производства материалов",
    description_tntesutyun_title3: "Промышленность",
    description_tntesutyun_sub1: "Ключевые отрасли промышленности:",
    description_tntesutyun_item9:
      "Горнодобывающая промышленность - медь (Каджаран, Агарак), молибден, золото (Сотк), драгоценные камни. Крупное предприятие: Зангезурский медно-молибденовый комбинат.",
    description_tntesutyun_item10:
      "Производство строительных материалов - туф, базальт, гранит, пемза, обсидиан, и т. д.",
    description_tntesutyun_item11:
      "Легкая промышленность – текстиль, шитье, вязание, обувь, ковроткачество ('Мегерянский ковер', 'Туфенкянский').",
    description_tntesutyun_item12:
      "Пищевая промышленность – консервы, вино, бренди, розлив минеральной воды.",
    description_tntesutyun_title4: "Основные экспортные товары",
    description_tntesutyun_item13:
      "Медь, молибден, золото, строительные материалы",
    description_tntesutyun_item14: "Алкогольные напитки",
    description_tntesutyun_item15:
      "Сельскохозяйственная продукция (фрукты, овощи, мед)",
    description_tntesutyun_item16: "Минеральная вода",
    description_tntesutyun_item17: "Текстиль и ковры",
    description_gyuxatntesutyun_title: "Сельское хозяйство",
    description_gyuxatntesutyun_sub: "Основные направления",
    description_gyuxatntesutyun_item1:
      "Зерновые культуры: пшеница, ячмень, рожь",
    description_gyuxatntesutyun_item2:
      "Овощеводство: помидоры, огурцы, баклажаны, картофель, редис, перец, шпинат, капуста, брокколи",
    description_gyuxatntesutyun_item3:
      "Фруктоводство: абрикосы, гранаты, персики, сливы, виноград, черешня (долина Арарат)",
    description_gyuxatntesutyun_item4:
      "Фермы: развитие мелких и средних фермерских хозяйств",
    description_anasnapahutyun_title: "Животноводство и пчеловодство",
    description_anasnapahutyun_item1:
      "Крупный рогатый скот, овцеводство, свиноводство, птицеводство",
    description_anasnapahutyun_item2:
      "Пчеловодство с древними традициями (упомянутыми Ксенофоном)",
    description_anasnapahutyun_title1: "Нематериальный сектор производства",
    description_anasnapahutyun_sub: "Торговля",
    description_anasnapahutyun_item3: "Розничная и оптовая торговля",
