      "Супермаркеты, торговые центры, рынки, специализированные магазины",
    description_anasnapahutyun_item5:
      "Развитие электронной коммерции (e-commerce)",
    description_anasnapahutyun_title2: "Услуги",
    description_turizm1: "ТУРИЗМ",
    description_turizm2:
      "Туризм — один из самых быстрорастущих секторов армянской экономики. Развивается ряд направлений:",
    description_turizm3: "Природный и приключенческий туризм",
    description_turizm4: "Культурно-исторический",
    description_turizm5: "Вино и гастрономический",
    description_turizm6: "Эко- и медицинский туризм",
    description_turizm7:
      "Число туристов растет с каждым годом. Развитие туристических услуг стимулирует гостиничный, транспортный и инфраструктурный секторы. Существуют:",
    description_turizm8: "Въездные и внутренние туристические пакеты",
    description_turizm9: "Услуги гида и переводчика",
    description_turizm10: "Гостиницы, гостевые дома, туристические центры",
    description_turizm11: "Транспорт и логистика",
    description_turizm12:
      "Транспорт и логистика обеспечивают мобильность и Торговые потоки не только населения, но и туристов. Армения развила:",
    description_turizm13:
      "Автомобильное сообщение (межрегиональное и городское)",
    description_turizm14:
      "Воздушный транспорт (международные аэропорты Еревана и Гюмри)",
    description_turizm15:
      "Железнодорожное сообщение, включая грузовые перевозки",
    description_turizm16:
      "Туристические перевозки и технологические приложения: GG, Yandex Go, Utaxi",
    description_turizm17:
      "Прокат автомобилей, пассажирские перевозки, автобусные перевозки",
    description_turizm18:
      "Транспортный сектор также тесно связан с международной логистикой, обеспечивая грузовые перевозки, функционирование логистических центров и применение инновационных решений.",
    description_turizm19: "Информационные технологии (ИТ)",
    description_turizm20: "Программирование, ИИ, инновационные решения",
    description_turizm21:
      "Быстро развивающаяся отрасль с зарубежными партнерами рынки",
    description_turizm22: "Финансы",
    description_turizm23:
      "Местные и международные банки, страхование, кредитные услуги",
    description_turizm24: "Юридические и консультационные услуги",
    description_turizm25:
      "Законодательная поддержка, бизнес-консалтинг, поддержка предприятий и частных лиц в области права и управления",
    description_turizm26: "Общественное питание",
    description_turizm27:
      "Рестораны, кафе, сети быстрого питания - местные и международные",
    description_turizm28: "Здравоохранение",
    description_turizm29:
      "Медицинские центры, клиники, аптеки и медицинские услуги",
    description_turizm30: "Наука",
    description_turizm31: "Математика, медицина, астрономия",
    description_turizm32: "Обсерватория Бюракан, Институт Физика",
    description_turizm33: "Образование и культура",
    description_turizm34: "Школы, университеты, культурные учреждения",
    description_turizm35: "Структура ВВП РА по секторам",
    description_turizm36: "Сектор",
    description_turizm37: "Процент (прибл.)",
    description_turizm38: "Пояснение",
    description_turizm39: "Торговля и услуги",
    description_turizm40: "61%",
    description_turizm41: "Торговля, ИТ, туризм, финансы, здравоохранение",
    description_turizm42: "Промышленность",
    description_turizm43: "52%",
    description_turizm44:
      "Горнодобывающая промышленность, переработка, строительство",
    description_turizm45: "Сельское хозяйство",
