    hayastan_info92: "Почтовая служба",
    hayastan_info93:
      "АО «Сейпост» — национальный почтовый оператор Армении, предоставляющий почтовые, финансовые и розничные услуги. Эти услуги предоставляются через более чем 900 почтовых отделений, работающих во всех городах и сельских районах Республики Армения.",
